+function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
+  const phpLoc = [
+    `    location ~ \\.php$ {`,
+    `        include fastcgi_params;`,
+    `        fastcgi_pass unix:${sock};`,
+    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
+    `    }`,
+  ].join("\n");
